import { test, expect } from '@playwright/test';

test.describe('Element Manager', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/add_remove_elements/');
  });

  test('should add two elements and verify their presence', async ({ page }) => {
    await page.getByText('Add Element').click();
    await page.getByText('Add Element').click();

    const addedElements = await page.locator('.added-manually').count();
    expect(addedElements).toBe(2);
  });

  test('should delete one element and verify one remains', async ({ page }) => {
    await page.getByText('Add Element').click();
    await page.getByText('Add Element').click();

    await page.locator('.added-manually').first().click();

    const remainingElements = await page.locator('.added-manually').count();
    expect(remainingElements).toBe(1);
  });
});
